<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Jelajahi produk dan toko UMKM Rembang."><meta name="robots" content="noindex,nofollow"><title><?= $selected_category ? html_escape($selected_category['name']).' — ' : '' ?>Belanja Produk Rembang</title><link rel="icon" href="<?= base_url('assets/favicon.ico?v=1') ?>"><link rel="stylesheet" href="<?= base_url('assets/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/marketplace.css?v=5') ?>"><link rel="stylesheet" href="<?= base_url('assets/market-nearby.css?v=3') ?>"></head>
<body class="shop-body"><?php $this->load->view('market/_header'); ?>
<main class="shop-main container-xl">
    <section id="kategori" class="shop-category-section"><div class="shop-section-head"><div><span class="shop-eyebrow">JELAJAHI REMBANG</span><h1>Kategori pilihan</h1></div><a href="<?= site_url('daftar-toko') ?>">Lihat toko <span aria-hidden="true">→</span></a></div><div class="shop-category-grid"><a class="shop-category-item <?= !$selected_category ? 'selected' : '' ?>" href="<?= html_escape(site_url('jelajah').($nearby?'?'.http_build_query(array('lat'=>$nearby[0],'lng'=>$nearby[1])):'')) ?>"><span class="shop-category-art all"><svg viewBox="0 0 96 96" aria-hidden="true"><circle cx="29" cy="29" r="11"/><circle cx="67" cy="29" r="11"/><circle cx="29" cy="67" r="11"/><circle cx="67" cy="67" r="11"/></svg></span><span>Semua</span></a><?php $near_params=array('category'=>$selected_category?$selected_category['slug']:'','q'=>$query); $near_target=site_url('jelajah').'?'.http_build_query(array_filter($near_params)); $this->load->view('market/_nearby_action',array('nearby'=>$nearby,'target'=>$near_target)); ?><?php foreach ($categories as $category): ?><a class="shop-category-item <?= $selected_category && $selected_category['id'] == $category['id'] ? 'selected' : '' ?>" href="<?= html_escape(site_url('jelajah').'?'.http_build_query(array_merge(array('category'=>$category['slug']),$nearby?array('lat'=>$nearby[0],'lng'=>$nearby[1]):array()))) ?>"><span class="shop-category-art"><img src="<?= category_art_url($category['slug']) ?>" alt="" loading="lazy"></span><span><?= html_escape($category['name']) ?></span></a><?php endforeach; ?></div><?php if($nearby): ?><p class="shop-nearby-note">Urutan perkiraan dari lokasi toko atau area kecamatan. <a href="<?= html_escape($near_target) ?>">Hapus urutan</a></p><?php endif; ?></section>
    <?php if ($banner): $banner_href = $banner['cta_target'] === 'stores' ? site_url('daftar-toko') : ($banner['cta_target'] === 'map' ? site_url('peta') : '#produk'); ?>
    <section class="shop-banner <?= $banner['image_path'] ? 'has-image' : '' ?>" aria-label="Pilihan produk lokal">
        <?php if ($banner['image_path']): ?><img class="shop-banner-photo" src="<?= base_url('assets/banners/'.$banner['image_path']) ?>" alt="" loading="eager"><?php endif; ?>
        <div class="shop-banner-copy"><span><?= html_escape($banner['eyebrow']) ?></span><h2><?= html_escape($banner['title']) ?></h2><p><?= html_escape($banner['subtitle']) ?></p><a href="<?= html_escape($banner_href) ?>"><?= html_escape($banner['cta_label']) ?> <span aria-hidden="true">→</span></a></div>
        <?php if (!$banner['image_path']): ?><div class="banner-visual" aria-hidden="true"><div class="banner-disc"></div><div class="banner-bag"><span>R</span></div><span class="banner-spark spark-one">✦</span><span class="banner-spark spark-two">✳</span></div><?php endif; ?>
    </section>
    <?php endif; ?>
    <section id="produk" class="shop-products-section"><div class="shop-section-head"><div><span class="shop-eyebrow">PILIHAN UNTUKMU</span><h2><?= $query !== '' ? 'Hasil untuk “'.html_escape($query).'”' : ($selected_category ? html_escape($selected_category['name']) : 'Temukan produk menarik') ?></h2></div><span class="shop-result-count"><?= number_format($total_products, 0, ',', '.') ?> produk</span></div>
    <?php if (!$products): ?><?php if ($featured_stores): ?><div class="shop-empty"><strong>Produk sedang dilengkapi oleh toko</strong><p>Jelajahi toko UMKM yang sudah tersedia dan hubungi pemiliknya langsung.</p><a href="<?= site_url('daftar-toko') ?>">Lihat semua toko</a></div><div class="shop-store-grid"><?php foreach($featured_stores as $store): ?><a class="shop-store-card" href="<?= site_url('toko/'.$store['slug']) ?>"><span class="shop-store-icon"><img src="<?= category_art_url($store['category_slug'] ?: 'ritel') ?>" alt="" loading="lazy"></span><span class="shop-store-info"><strong><?= html_escape($store['display_name']) ?></strong><small>⌖ <?= html_escape($store['district_name'] ?: 'Kabupaten Rembang') ?></small><em>Lihat toko</em></span><span class="shop-store-arrow" aria-hidden="true">→</span></a><?php endforeach; ?></div><?php else: ?><div class="shop-empty"><strong>Produk belum ditemukan</strong><p>Coba kata kunci lain atau pilih kategori berbeda.</p><a href="<?= site_url('jelajah') ?>">Lihat semua produk</a></div><?php endif; ?><?php else: ?><div class="shop-product-grid"><?php foreach ($products as $product): ?><article class="shop-product-card"><a class="shop-product-link" href="<?= site_url('produk/'.$product['id']) ?>"><div class="shop-product-image <?= $product['cover_path'] ? 'has-photo' : '' ?>"><img src="<?= ($product['cover_path'] ? base_url('assets/products/'.rawurlencode($product['cover_path'])) : category_art_url($product['category_slug'] ?: 'kuliner')) ?>" alt="" loading="lazy"><span class="shop-product-origin">Rembang</span></div><div class="shop-product-info"><h3><?= html_escape($product['name']) ?></h3><strong><?= $product['price_min'] !== NULL ? 'Rp'.number_format((float) $product['price_min'], 0, ',', '.') : 'Tanya harga' ?></strong><small><?= html_escape($product['store_name']) ?></small><span>⌖ <?= html_escape($product['district_name'] ?: 'Rembang') ?></span></div></a><?php if ((int)$product['variant_count']>0): ?><a class="shop-quick-add shop-choose-variant" href="<?= site_url('produk/'.$product['id']) ?>" aria-label="Pilih variasi <?= html_escape($product['name']) ?>">Pilih</a><?php else: ?><form method="post" action="<?= site_url('keranjang/tambah') ?>" class="shop-quick-add"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="product_id" value="<?= (int) $product['id'] ?>"><input type="hidden" name="quantity" value="1"><button type="submit" aria-label="Tambah <?= html_escape($product['name']) ?> ke keranjang">+</button></form><?php endif; ?></article><?php endforeach; ?></div>
    <?php $pagination_base = site_url('jelajah'); $pagination_params = array(); if ($selected_category) $pagination_params['category'] = $selected_category['slug']; if ($query !== '') $pagination_params['q'] = $query; if ($nearby) { $pagination_params['lat']=$nearby[0];$pagination_params['lng']=$nearby[1]; } $this->load->view('market/_pagination', array('pagination_base' => $pagination_base, 'pagination_params' => $pagination_params, 'page' => $page, 'total_pages' => $total_pages)); ?>
    <?php endif; ?></section>
</main><?php $active_tab = 'home'; $this->load->view('market/_bottom_nav', array('active_tab' => $active_tab, 'cart_count' => $cart_count)); ?></body></html>
